@namespace sv_6906c65358f5492eb5199b0e8901b2a6.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var step = i;
            var status = GetStepStatus(step);
            <li class="step-item @status" @onclick="() => OnStepClick(step)" role="button" tabindex="0">
                <span class="step-marker">
                    @if (status == "completed")
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        @(step + 1)
                    }
                </span>
                <span class="step-label">@Steps[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@namespace sv_6906c65358f5492eb5199b0e8901b2a6.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="e => UpdateEntry(Entry with { Company = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="e => UpdateEntry(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!) })" />
        </div>
    </div>

    <div class="form-group form-check">
        <input type="checkbox" class="form-check-input" checked="@IsCurrent"
               @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
        <label class="form-check-label">I currently work here</label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private async Task UpdateEntry(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

@namespace sv_6906c65358f5492eb5199b0e8901b2a6.Components.Pages.Apply

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    <div class="form-group">
