@namespace sv_6906c65358f5492eb5199b0e8901b2a6.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Please save this number for your records.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl>
                    <dt>Name</dt><dd>@Personal.FullName</dd>
                    <dt>Email</dt><dd>@Personal.Email</dd>
                    <dt>Phone</dt><dd>@Personal.Phone</dd>
                    <dt>Address</dt><dd>@Personal.Address</dd>
                </dl>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @if (WorkEntries is not null)
            {
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small>@entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"• {r.Phone}" : "")</small>
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-actions">
            <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public List<WorkEntry>? WorkEntries { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (Personal is null || WorkEntries is null || References is null)
        {
            ErrorMessage = "Application data is incomplete.";
            return;
        }

        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            var application = new JobApplication(
                Personal,
                new WorkHistory(WorkEntries),
                References,
                CoverLetter ?? string.Empty
            );

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

