@page "/apply"
@namespace sv_6906c65358f5492eb5199b0e8901b2a6.Components.Pages.Apply
@using sv_6906c65358f5492eb5199b0e8901b2a6.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="@personalInfo"
                              ApplicationService="@ApplicationService"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep InitialEntries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep InitialReferences="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep InitialText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        ApplicationService="@ApplicationService"
                        OnEditStep="GoToStep"
                        OnBack="GoBack" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfo? personalInfo;
    private List<WorkEntry>? workEntries;
    private List<Reference>? references;
    private string? coverLetter;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 1.5rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-marker {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    margin-bottom: 0.5rem;
}

.step-item.active .step-marker {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-marker {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-item.dimmed .step-marker {
    opacity: 0.5;
}

.step-label {
    font-size: 0.8rem;
    text-align: center;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.dimmed .step-label {
    opacity: 0.5;
}

.checkmark {
    font-size: 1.1rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.5rem;
}

.step-content h3 {
    margin-bottom: 1.5rem;
    color: #212529;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #495057;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    line-height: 1.5;
    box-sizing: border-box;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: 0;
    box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.form-check {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.form-check-input {
    width: 1rem;
    height: 1rem;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.5rem 1rem;
    font-size: 1rem;
    border: 1px solid transparent;
    border-radius: 4px;
    cursor: pointer;
    text-decoration: none;
}

.btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #0d6efd;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background-color: #0b5ed7;
}

.btn-secondary {
    background-color: #6c757d;
    color: #fff;
}

.btn-outline-secondary {
    border-color: #6c757d;
    color: #6c757d;
    background: transparent;
}

.btn-outline-secondary:hover {
    background: #6c757d;
    color: #fff;
}

.btn-danger {
    background-color: #dc3545;
    color: #fff;
}

.btn-success {
    background-color: #198754;
    color: #fff;
}

.btn-success:hover:not(:disabled) {
    background-color: #157347;
}

.btn-lg {
    padding: 0.75rem 1.5rem;
    font-size: 1.1rem;
}

.btn-sm {
    padding: 0.25rem 0.5rem;
    font-size: 0.875rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    padding: 0;
    font-size: 0.9rem;
    cursor: pointer;
    text-decoration: underline;
}

/* Step Actions */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Alerts */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.alert-danger {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.alert-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

/* Work Entry Form */
.work-entry-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
}

/* Reference Form */
.reference-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.reference-form h4 {
    margin: 0 0 1rem 0;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.character-count {
    display: block;
    text-align: right;
    margin-top: 0.25rem;
}

/* Review */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #495057;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #e9ecef;
}

.review-entry:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 4px;
}

/* Utility */
.text-muted {
    color: #6c757d;
}

.text-warning {
    color: #ffc107;
}

