toolArgs.file_text:
@page "/apply"
@namespace sv_6906c65358f5492eb5199b0e8901b2a6.Components.Pages.Apply
@using sv_6906c65358f5492eb5199b0e8901b2a6.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="@personalInfo"
                              ApplicationService="@ApplicationService"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep InitialEntries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep InitialReferences="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep InitialText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        ApplicationService="@ApplicationService"
                        OnEditStep="GoToStep"
                        OnBack="GoBack" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfo? personalInfo;
    private List<WorkEntry>? workEntries;
    private List<Reference>? references;
    private string? coverLetter;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }
}

