@namespace sv_6906c65358f5492eb5199b0e8901b2a6.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="HandleCompanyChange" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="HandleTitleChange" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="HandleStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDateValue"
                   disabled="@IsCurrent"
                   @onchange="HandleEndDateChange" />
        </div>
    </div>

    <div class="form-group form-check">
        <input type="checkbox" class="form-check-input" checked="@IsCurrent"
               @onchange="HandleCurrentToggle" />
        <label class="form-check-label">I currently work here</label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="HandleDescriptionChange"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;
    private string EndDateValue => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task HandleCompanyChange(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Company = e.Value?.ToString() ?? string.Empty });

    private Task HandleTitleChange(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Title = e.Value?.ToString() ?? string.Empty });

    private Task HandleStartDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { StartDate = date });
    }

    private Task HandleEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task HandleDescriptionChange(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Description = e.Value?.ToString() ?? string.Empty });

    private Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        return OnEntryChanged.InvokeAsync(updated);
    }
}

